/// Scans the next token, if any.
fn scan(&mut self) -> Result<Option<Token>> {
    self.skip_whitespace();
    Ok(self.scan_ident_or_keyword()
        .or_else(|| self.scan_ident_quoted().ok().flatten())
        .or_else(|| self.scan_number())
        .or_else(|| self.scan_string().ok().flatten())
        .or_else(|| self.scan_symbol()))
}
